\set ON_ERROR_STOP on
begin;
create temporary table device_assertions(n integer not null default 0);insert into device_assertions default values;grant select,update on device_assertions to service_role;
create function pg_temp.ok(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'DEVICE SESSION FAIL: %',label;end if;update device_assertions set n=n+1;end$$;
create function pg_temp.refuse(command text,prefix text,label text)returns void language plpgsql as $$begin begin execute command;exception when raise_exception then if sqlerrm like prefix||'%'then perform pg_temp.ok(true,label);return;end if;raise;end;raise exception 'DEVICE SESSION FAIL: allowed %',label;end$$;
insert into auth.users(id,email,is_anonymous)values('f8100000-0000-4000-8000-000000000001','device-a@fixture.invalid',false),('f8100000-0000-4000-8000-000000000002','device-b@fixture.invalid',false);
set local role service_role;
select notification_register_device_session('f8100000-0000-4000-8000-000000000001','f8200000-0000-4000-8000-000000000001',repeat('ab',32),'com.rendprop.app','sandbox','en','55');
select pg_temp.ok(exists(select 1 from notification_devices where device_token=repeat('ab',32)and user_id='f8100000-0000-4000-8000-000000000001'),'A session initially registers the actual token');
select pg_temp.ok((notification_unregister_device('f8100000-0000-4000-8000-000000000001','f8200000-0000-4000-8000-000000000001',repeat('ab',32),'sandbox')->>'unregistered')::boolean,'A barrier unregisters its own token');
select notification_register_device_session('f8100000-0000-4000-8000-000000000002','f8200000-0000-4000-8000-000000000002',repeat('ab',32),'com.rendprop.app','sandbox','en','55');
select pg_temp.refuse($q$select notification_register_device_session('f8100000-0000-4000-8000-000000000001','f8200000-0000-4000-8000-000000000001',repeat('ab',32),'com.rendprop.app','sandbox','en','55')$q$,'RP409: This device session has signed out','late A POST cannot resurrect after B register');
select pg_temp.ok(exists(select 1 from notification_devices where device_token=repeat('ab',32)and user_id='f8100000-0000-4000-8000-000000000002'),'B token ownership survives the late A POST');
select pg_temp.ok(not(notification_unregister_device('f8100000-0000-4000-8000-000000000001','f8200000-0000-4000-8000-000000000001',repeat('ab',32),'sandbox')->>'removed')::boolean,'late A DELETE removes no B binding');
select pg_temp.ok(exists(select 1 from notification_devices where device_token=repeat('ab',32)and user_id='f8100000-0000-4000-8000-000000000002'),'B token ownership survives late A DELETE');
select notification_register_device_session('f8100000-0000-4000-8000-000000000001','f8200000-0000-4000-8000-000000000001',repeat('cd',32),'com.rendprop.app','sandbox','en','55');
select pg_temp.ok(exists(select 1 from notification_devices where device_token=repeat('cd',32)and user_id='f8100000-0000-4000-8000-000000000001'),'tombstone does not revoke another token');
select notification_register_device_session('f8100000-0000-4000-8000-000000000001','f8200000-0000-4000-8000-000000000003',repeat('ab',32),'com.rendprop.app','sandbox','en','55');
select pg_temp.ok(exists(select 1 from notification_devices where device_token=repeat('ab',32)and user_id='f8100000-0000-4000-8000-000000000001'),'a genuine new A session can register after new sign-in');
select pg_temp.ok((notification_unregister_device('f8100000-0000-4000-8000-000000000001','f8200000-0000-4000-8000-000000000001',upper(repeat('ab',32)),'sandbox')->>'unregistered')::boolean,'repeated case-varied DELETE acknowledges durable fence');
select pg_temp.ok(exists(select 1 from notification_devices where device_token=repeat('ab',32)and user_id='f8100000-0000-4000-8000-000000000001'and registration_session_id='f8200000-0000-4000-8000-000000000003'),'late old A session DELETE preserves newer A session');
select pg_temp.refuse($q$select notification_register_device_session('f8100000-0000-4000-8000-000000000001','f8200000-0000-4000-8000-000000000001',upper(repeat('ab',32)),'com.rendprop.app','sandbox','en','55')$q$,'RP409: This device session has signed out','uppercase token cannot bypass lowercase session tombstone');
select pg_temp.ok((notification_unregister_device('f8100000-0000-4000-8000-000000000001','f8200000-0000-4000-8000-000000000001',repeat('ef',32),'sandbox')->>'unregistered')::boolean,'missing-token DELETE still durably fences delayed POST');
select pg_temp.refuse($q$select notification_register_device_session('f8100000-0000-4000-8000-000000000001','f8200000-0000-4000-8000-000000000001',repeat('ef',32),'com.rendprop.app','sandbox','en','55')$q$,'RP409:','absent initial registration cannot resurrect after successful barrier');

select notification_register_device_session('f8100000-0000-4000-8000-000000000001','f8200000-0000-4000-8000-000000000001',repeat('ab',32),'com.rendprop.app','production','en','55');
select pg_temp.ok(exists(select 1 from notification_devices where device_token=repeat('ab',32)and environment='production'),'sandbox session tombstone does not block production registration');
select pg_temp.refuse($q$select notification_register_device_session('f8100000-0000-4000-8000-000000000001',null,repeat('ab',32),null,'sandbox',null,null)$q$,'RP400:','register requires verified session identity');
select pg_temp.refuse($q$select notification_unregister_device('f8100000-0000-4000-8000-000000000001',null,repeat('ab',32),'sandbox')$q$,'RP400:','unregister requires verified session identity');
select pg_temp.refuse($q$select notification_unregister_device('f8100000-0000-4000-8000-000000000001','f8200000-0000-4000-8000-000000000001','not a token','sandbox')$q$,'RP400:','unregister validates token shape');
reset role;
select pg_temp.ok((select count(*)=2 from notification_device_session_tombstones where user_id='f8100000-0000-4000-8000-000000000001'and session_id='f8200000-0000-4000-8000-000000000001'),'unregister replay keeps one exact fence per canonical token');
select pg_temp.ok(not has_table_privilege('anon','public.notification_device_session_tombstones','select')and not has_table_privilege('authenticated','public.notification_device_session_tombstones','select')and not has_table_privilege('service_role','public.notification_device_session_tombstones','insert'),'no direct tombstone table access');
select pg_temp.ok((select relrowsecurity from pg_class where oid='public.notification_device_session_tombstones'::regclass)and not exists(select 1 from pg_policy where polrelid='public.notification_device_session_tombstones'::regclass),'tombstones have RLS deny-all');
select pg_temp.ok(not has_function_privilege('anon','public.notification_unregister_device(uuid,uuid,text,text)','execute')and not has_function_privilege('authenticated','public.notification_unregister_device(uuid,uuid,text,text)','execute'),'unregister helper is service-only');
select pg_temp.ok(not has_function_privilege('anon','public.notification_register_device_session(uuid,uuid,text,text,text,text,text)','execute')and not has_function_privilege('authenticated','public.notification_register_device_session(uuid,uuid,text,text,text,text,text)','execute'),'session register helper is service-only');
select pg_temp.ok((select bool_and(prosecdef and proconfig=array['search_path=""']::text[])from pg_proc where oid in('public.notification_unregister_device(uuid,uuid,text,text)'::regprocedure,'public.notification_register_device_session(uuid,uuid,text,text,text,text,text)'::regprocedure)),'both helpers bind empty search path');
select pg_temp.ok(not exists(select 1 from pg_constraint where conrelid='public.notification_device_session_tombstones'::regclass and contype='f'and confrelid=(select oid from pg_class where relnamespace='auth'::regnamespace and relname='sessions')),'Auth session expiry cannot erase the device fence');
select notification_register_device('f8100000-0000-4000-8000-000000000001',upper(repeat('dd',32)),null,'sandbox',null,null);
select notification_register_device_session('f8100000-0000-4000-8000-000000000002','f8200000-0000-4000-8000-000000000002',repeat('dd',32),null,'sandbox',null,null);
select pg_temp.ok((select count(*)=1 and bool_and(device_token=repeat('dd',32)and user_id='f8100000-0000-4000-8000-000000000002')from notification_devices where lower(device_token)=repeat('dd',32)),'legacy uppercase device canonicalizes into one exact token binding');
set local role service_role;
select prepare_account_deletion('f8100000-0000-4000-8000-000000000001','synthetic-uploads','synthetic-renders');
reset role;
-- Auth deletion is the next real API cleanup step after preparation.
delete from auth.users where id='f8100000-0000-4000-8000-000000000001';
select pg_temp.ok(not exists(select 1 from notification_device_session_tombstones where user_id='f8100000-0000-4000-8000-000000000001'),'actual preparation followed by Auth cascade removes its session tombstones');
select pg_temp.ok(exists(select 1 from notification_devices where device_token=repeat('dd',32)and user_id='f8100000-0000-4000-8000-000000000002'),'actual account removal preserves the other account device binding');
select jsonb_build_object('suite','notification_session_fencing','assertions',n,'late_registration_refused',true,'late_delete_keeps_new_account',true)from device_assertions;
rollback;
